func conditionMatches(condition, sourcePath string, ctx *configIncludeContext) bool {
	if condition == "" {
		return true
	}

	if pattern, ok := strings.CutPrefix(condition, "gitdir:"); ok {
		return matchGitDirs(pattern, sourcePath, ctx.gitDirs, false)
