package config_test

import (
 "os"
 "path/filepath"
 "testing"

 "github.com/go-git/cli/internal/plumbing/format/config"
)

func TestUpdateFilePreservesPhysicalPath(t *testing.T) {
 t.Parallel()
 for _, tc := range []struct{name, path, link string; missing bool}{
  {name: "parent traversal", path: "jump/../cfg"},
  {name: "link payload", path: "link", link: "jump/../cfg"},
  {name: "dangling payload", path: "link", link: "jump/../cfg", missing: true},
  {name: "missing final file", path: "jump/../cfg", missing: true},
 } {
  t.Run(tc.name, func(t *testing.T) {
   t.Parallel()
   dir := t.TempDir()
   if err := os.MkdirAll(filepath.Join(dir, "real", "sub"), 0o755); err != nil {t.Fatal(err)}
   if err := os.Symlink("real/sub", filepath.Join(dir, "jump")); err != nil {t.Skip(err)}
   if tc.link != "" {if err := os.Symlink(tc.link, filepath.Join(dir,"link")); err != nil {t.Fatal(err)}}
   other := filepath.Join(dir,"cfg")
   intended := filepath.Join(dir,"real","cfg")
   original := []byte("[a]\nb = original\n")
   if err := os.WriteFile(other, original, 0o644); err != nil {t.Fatal(err)}
   if !tc.missing {if err := os.WriteFile(intended, original, 0o644); err != nil {t.Fatal(err)}}
   path := dir + "/" + tc.path
   if err := config.UpdateFile(path, func(f *config.File) error {return f.Set(mustKey(t,"a.b"),"updated")}); err != nil {t.Fatal(err)}
   f, err := config.ReadFile(path)
   if err != nil {t.Fatal(err)}
   if got, ok := f.Get(mustKey(t,"a.b")); !ok || got != "updated" {t.Fatalf("read selected path = %q, %v",got,ok)}
   data, err := os.ReadFile(other)
   if err != nil || string(data) != string(original) {t.Fatalf("unintended file changed: %q, %v",data,err)}
   f, err = config.ReadFile(intended)
   if err != nil {t.Fatal(err)}
   if got, ok := f.Get(mustKey(t,"a.b")); !ok || got != "updated" {t.Fatalf("physical target = %q, %v",got,ok)}
   if _, err := os.Stat(intended+".lock"); !os.IsNotExist(err) {t.Fatalf("lock remains: %v",err)}
  })
 }
}

func TestUpdateFileRejectsInvalidTraversal(t *testing.T) {
 t.Parallel()
 for _, path := range []string{"missing/../cfg", "plain/../cfg", "loop/cfg", "loop", "missing/cfg"} {
  t.Run(path, func(t *testing.T) {
   t.Parallel()
   dir := t.TempDir()
   if err := os.WriteFile(filepath.Join(dir,"plain"),nil,0o644); err != nil {t.Fatal(err)}
   if err := os.Symlink("loop",filepath.Join(dir,"loop")); err != nil {t.Skip(err)}
   called := false
   err := config.UpdateFile(dir+"/"+path,func(*config.File) error {called = true; return nil})
   if err == nil || called {t.Fatalf("invalid traversal accepted: error %v, mutation %v",err,called)}
   if _, err := os.Stat(filepath.Join(dir,"cfg")); !os.IsNotExist(err) {t.Fatalf("created unintended config: %v",err)}
  })
 }
}
