   {name:"local conflict",flags:[]string{flagLocal},wantCode:129},
   {name:"global conflict",flags:[]string{flagGlobal},wantCode:129},
   {name:"system conflict",flags:[]string{"--system"},wantCode:129},
   {name:"empty environment conflict",envEmpty:true,flags:[]string{flagLocal},wantCode:129},
  } {
   name := "legacy/"+tc.name
   if modern {name = "modern/"+tc.name}
   t.Run(name,func(t *testing.T) {
    t.Parallel()
    repo, home := newConfigRepo(t,"[x]\na = repository\n")
    writeConfig(t,filepath.Join(repo,"selected"),"[x]\na = selected\n")
    writeConfig(t,filepath.Join(repo,"explicit"),"[x]\na = explicit\n")
    before := map[string]string{}
    for _, path := range []string{".git/config","selected","explicit"} {before[path]=readFileString(t,filepath.Join(repo,path))}
    value := "selected"
    if tc.envEmpty {value = ""}
    env := []string{"GIT_CONFIG="+value}
    read, write := []string{cmdConfig}, []string{cmdConfig}
    if modern {read=append(read,subGet);write=append(write,subSet)}
    read=append(read,tc.flags...);write=append(write,tc.flags...)
    if !modern {read=append(read,flagGet)}
