    if wantRead == 4 {wantRead = 1}
    out, stderr, code := runIsolatedConfig(t,repo,home,env,read)
    if code != wantRead || (wantRead == 0 && out != tc.target+"\n") {t.Fatalf("read = %q, %d, %s",out,code,stderr)}
