				t.Fatal(err)
			}
			if !tc.missing {
				if err := os.WriteFile(intended, original, 0o644); err != nil {
					t.Fatal(err)
				}
			}
			path := dir + "/" + tc.path
			if err := config.UpdateFile(path, func(f *config.File) error { return f.Set(mustKey(t, "a.b"), "updated") }); err != nil {
