			}
			f, err := config.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			if got, ok := f.Get(mustKey(t, "a.b")); !ok || got != "updated" {
				t.Fatalf("read selected path = %q, %v", got, ok)
