func validRepositoryHEAD(path string) bool {
	info, err := os.Lstat(path)
	if err != nil {
		return false
	}

	if info.Mode()&os.ModeSymlink != 0 {
		target, err := os.Readlink(path)

		return err == nil && strings.HasPrefix(target, "refs/")
	}

	if !info.Mode().IsRegular() {
		return false
	}

	file, err := os.Open(path)
	if err != nil {
		return false
	}
	defer file.Close()

	data, err := io.ReadAll(io.LimitReader(file, 255))
	if err != nil {
		return false
	}

	if ref, ok := strings.CutPrefix(string(data), "ref:"); ok {
		return strings.HasPrefix(strings.TrimLeft(ref, " \t\n\r\v\f"), "refs/")
	}
	// Repository discovery accepts detached HEADs before checking object existence.
	if len(data) < 40 {
		return false
	}

	_, err = hex.DecodeString(string(data[:40]))

	return err == nil
}

func isDir(path string) bool {
	info, err := os.Stat(path)

	return err == nil && info.IsDir()
}

func resolveWritePath(path string) (string, error) {
	if path == "" {
		return "", os.ErrNotExist
	}

	for range 255 {
		// Resolve the parent before joining: cleaning first changes symlink/.. traversal.
		parent, name := filepath.Split(path)
		if parent == "" {
			parent = "."
		}

		resolved, err := filepath.EvalSymlinks(parent)
		if err != nil {
			return "", err
		}

		resolved, err = filepath.Abs(resolved)
		if err != nil {
			return "", err
		}

		current := filepath.Join(resolved, name)

		info, err := os.Lstat(current)
		if err != nil {
			if os.IsNotExist(err) {
				return current, nil
			}

			return "", err
